using System;using System.Web;using System.Web.Services;using WebPortal.Assets.Classes;
namespace WebPortal.Assets{public partial class AssetMaintenance:System.Web.UI.Page{static AssetBAL S=>new AssetBAL();static long U=>Convert.ToInt64(HttpContext.Current.User.Identity.Name.ToString());protected void Page_Load(object sender,EventArgs e){}[WebMethod]public static object Lookup(string type,int? parentID){return AssetBAL.Rows(S.Lookup(type,parentID));}[WebMethod]public static object List(){return AssetBAL.Rows(S.List("Maintenance",null,null,"Open"));}[WebMethod]public static object Get(long id){return AssetBAL.Sets(S.Detail("Maintenance",id));}[WebMethod]public static ApiResult Save(MaintenanceInput x){try{return ApiResult.Ok(S.Save("usp_Assets_SaveMaintenance",x,U));}catch(Exception ex){return ApiResult.Fail(ex.Message);}}[WebMethod]public static ApiResult Action(long id,string action,string remarks){try{S.Action("Maintenance",id,action,remarks,U);return ApiResult.Ok();}catch(Exception ex){return ApiResult.Fail(ex.Message);}}}}
